create policy "Users can read own profile" on public.profiles for select to authenticated using (id = (select auth.uid()));
create policy "Users can create own profile" on public.profiles for insert to authenticated with check (id = (select auth.uid()));
create policy "Users can update own profile" on public.profiles for update to authenticated using (id = (select auth.uid())) with check (id = (select auth.uid()));
create policy "Authenticated users can discover businesses" on public.business_profiles for select to authenticated using (true);
create policy "Owners can create business profile" on public.business_profiles for insert to authenticated with check (owner_id = (select auth.uid()));
create policy "Owners can update business profile" on public.business_profiles for update to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy "Owners can delete business profile" on public.business_profiles for delete to authenticated using (owner_id = (select auth.uid()));
create policy "Connection participants can read" on public.connections for select to authenticated using (requester_id = (select auth.uid()) or recipient_id = (select auth.uid()));
create policy "Users can request connections as themselves" on public.connections for insert to authenticated with check (requester_id = (select auth.uid()));
create policy "Recipients can respond to requests" on public.connections for update to authenticated using (recipient_id = (select auth.uid())) with check (recipient_id = (select auth.uid()));
create policy "Conversation participants can read" on public.conversations for select to authenticated using (user_a = (select auth.uid()) or user_b = (select auth.uid()));
create policy "Conversation participants can create" on public.conversations for insert to authenticated with check ((user_a = (select auth.uid()) or user_b = (select auth.uid())));
create policy "Participants can read messages" on public.messages for select to authenticated using (exists (select 1 from public.conversations c where c.id = conversation_id and (c.user_a = (select auth.uid()) or c.user_b = (select auth.uid()))));
create policy "Participants can send own messages" on public.messages for insert to authenticated with check (sender_id = (select auth.uid()) and exists (select 1 from public.conversations c where c.id = conversation_id and (c.user_a = (select auth.uid()) or c.user_b = (select auth.uid()))));
create policy "Authenticated users can view open opportunities" on public.opportunities for select to authenticated using (status = 'open' or owner_id = (select auth.uid()));
create policy "Owners can create opportunities" on public.opportunities for insert to authenticated with check (owner_id = (select auth.uid()));
create policy "Owners can update opportunities" on public.opportunities for update to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy "Owners can delete opportunities" on public.opportunities for delete to authenticated using (owner_id = (select auth.uid()));
create policy "Users and opportunity owners can read responses" on public.opportunity_responses for select to authenticated using (responder_id = (select auth.uid()) or exists (select 1 from public.opportunities o where o.id = opportunity_id and o.owner_id = (select auth.uid())));
create policy "Users can respond as themselves" on public.opportunity_responses for insert to authenticated with check (responder_id = (select auth.uid()));
create policy "Users can read own notifications" on public.notifications for select to authenticated using (user_id = (select auth.uid()));
create policy "Users can update own notifications" on public.notifications for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
